  "Это деньги, вложенные в бизнес его владельцем, а также объём нераспределённой прибыли, которую бизнес успел заработать и реинвестировать в развитие или отложить в фонды. Размер капитала не статичен, он постоянно меняется. Чтобы его узнать, нужно из суммы всех активов вычесть сумму обязательств. Полученное значение — это те деньги, которые непосредственно работают в бизнесе": "Bu biznesga egasi tomonidan kiritilgan pul, shuningdek biznes topib, rivojlanishga qayta sarflagan yoki fondlarga ajratgan taqsimlanmagan foyda hajmi. Kapital hajmi o'zgarmas emas, doimiy o'zgarib turadi. Uni bilish uchun barcha aktivlar summasidan majburiyatlar summasini ayirish kerak. Olingan qiymat biznesda bevosita ishlayotgan pul.",
